123: fn identity(file: &File) -> Result<Identity> {
124:     let metadata = file.metadata()?;
125:     let mut stat = std::mem::MaybeUninit::<libc::statfs>::zeroed();
126:     // SAFETY: stat is writable and the borrowed descriptor remains live.
127:     syscall(unsafe { libc::fstatfs(file.as_raw_fd(), stat.as_mut_ptr()) })?;
128:     // SAFETY: successful fstatfs initialized stat.
129:     let stat = unsafe { stat.assume_init() };
130:     if stat.f_type == 0x9123_683e {
