287:     // fully written and synced files acquire the transaction-owned stage name.
288:     // SAFETY: parent is pinned; O_TMPFILE creates a new owned inode.
289:     let fd = unsafe { libc::openat(parent.as_raw_fd(), c".".as_ptr(), libc::O_TMPFILE | libc::O_RDWR | libc::O_CLOEXEC, 0o600) };
290:     ensure!(fd >= 0, "create unnamed system stage: {}", std::io::Error::last_os_error());
291:     // SAFETY: successful openat transfers fd ownership.
292:     let mut file = unsafe { File::from_raw_fd(fd) };
293:     // Inherited default ACLs must fail while the inode is still unnamed, so
294:     // recovery never encounters an unsupported named stage that it cannot inspect.
295:     reject_xattrs(&file)?;
296:     let metadata = source.metadata()?;
297:     source.seek(SeekFrom::Start(0))?;
298:     std::io::copy(source, &mut file)?;
299:     // SAFETY: apply exact mode to our owned inode.
300:     syscall(unsafe { libc::fchmod(file.as_raw_fd(), mode) })?;
301:     let times = [
302:         libc::timespec { tv_sec: metadata.atime(), tv_nsec: metadata.atime_nsec() },
303:         libc::timespec { tv_sec: metadata.mtime(), tv_nsec: metadata.mtime_nsec() },
304:     ];
305:     // SAFETY: preserve the source's access/modification times on our new inode.
306:     syscall(unsafe { libc::futimens(file.as_raw_fd(), times.as_ptr()) })?;
307:     file.sync_all()?;
308:     let descriptor_path = CString::new(format!("/proc/self/fd/{}", file.as_raw_fd()))?;
309:     // SAFETY: this kernel-owned link names our live unnamed descriptor, not a
310:     // caller-supplied symlink; the destination is beneath the pinned parent.
311:     syscall(unsafe { libc::linkat(libc::AT_FDCWD, descriptor_path.as_ptr(), parent.as_raw_fd(), destination.as_ptr(), libc::AT_SYMLINK_FOLLOW) })?;
312:     Ok(parent.sync_all()?)
